"""Blocos HTML de imagens e créditos, partilhados pelo gerador estático."""
from html import escape as e
import json
from pathlib import Path
from conteudos.recursos import FOTOS_TECNICAS, PRODUTOS, POR_ID, CATALOGO
ROOT=Path(__file__).resolve().parents[1]

def tecnica(id,prefix='../'):
    f=FOTOS_TECNICAS[id]
    return f'''<figure class="technique-photo"><div class="technique-photo-frame"><img src="{prefix}assets/tecnicas/{f.get("ficheiro", id + ".webp")}" alt="{e(f['alt'])}" width="{f['width']}" height="{f['height']}" loading="lazy" decoding="async"></div><figcaption>Exemplo ilustrativo de terceiros: {e(f['titulo'].lower())}. Não representa a produção da Nobrinde. <span>Fotografia: {e(f['autor'])} · <a href="{prefix}creditos-imagens.html#{id}">{f['licenca']} — créditos e alterações</a></span></figcaption></figure>'''

def exemplos(ids,prefix='../',heading=True):
    if not (ROOT/'assets/produtos/manifesto.json').is_file():
        return ''
    sizes={p['id']:p for p in json.loads((ROOT/'assets/produtos/manifesto.json').read_text(encoding='utf-8'))}
    items=''
    for id in ids:
        p=POR_ID[id];size=sizes[id]
        items+=f'''<article class="product-example" id="produto-{id}"><figure><div class="product-photo-frame"><img src="{prefix}assets/produtos/{p['ficheiro']}" alt="{e(p['alt'])}" width="{size['width']}" height="{size['height']}" loading="lazy" decoding="async"></div><figcaption>Imagem do catálogo · Ref. {p['ref']}</figcaption></figure><div class="product-example-copy"><h3>{e(p['nome'])} <span>{p['ref']}</span></h3><ul>{''.join('<li>'+e(t)+'</li>' for t in p['factos'])}</ul><p>{e(p['leitura'])}</p><p class="catalogue-source"><a href="{prefix}creditos-imagens.html#catalogo-{id}">Catálogo 2026 · PDF p. {p['pdf']} · página impressa {p['impressa']}</a></p></div></article>'''
    grid='<div class="product-grid">'+items+'</div>'
    if not heading:return grid
    return '<section class="catalogue-examples" id="exemplos-catalogo"><h2>Exemplos documentados no catálogo</h2><p class="catalogue-intro">Referências para compreender materiais e variantes. As características correspondem à edição de 2026; não indicam disponibilidade atual nem trabalhos realizados pela Nobrinde.</p>'+grid+'</section>'

def creditos():
    # Autorização explícita do utilizador registada no seguimento editorial.
    html='<nav class="crumb" aria-label="Percurso"><a href="index.html">Início</a> / Créditos de imagens</nav><div class="page-intro"><span class="eyebrow">Fontes e atribuições</span><h1>Créditos de imagens</h1><p>Identificação das fotografias, das suas fontes e das alterações realizadas para esta biblioteca.</p></div><section><h2>Fotografias das técnicas</h2><p>São exemplos ilustrativos de terceiros. Não mostram instalações, equipamentos ou trabalhos da Nobrinde e não implicam o endosso dos autores.</p><div class="credits-grid">'
    for id,f in FOTOS_TECNICAS.items():
        share=' A versão adaptada mantém a licença '+f['licenca']+'.' if 'BY-SA' in f['licenca'] else ''
        html+=f'''<article class="credit-card" id="{id}"><img src="assets/tecnicas/{f.get("ficheiro", id + ".webp")}" alt="{e(f['alt'])}" width="{f['width']}" height="{f['height']}" loading="lazy"><h3>{f['titulo']}</h3><dl><dt>Autor</dt><dd>{e(f['autor'])}</dd><dt>Fonte</dt><dd><a href="{f['fonte']}">Fotografia original no Wikimedia Commons</a></dd><dt>Licença</dt><dd><a href="{f['licenca_url']}">{f['licenca']}</a></dd><dt>Alterações</dt><dd>Redimensionamento e conversão de JPEG para WebP, sem recorte.{share}</dd></dl></article>'''
    html+='</div><p class="catalogue-intro">Atribuições conforme o ficheiro LEIA-ME-creditos.md fornecido com as imagens. A atribuição da imagem CC0 é mantida para transparência. Estas licenças aplicam-se às respetivas fotografias, não às imagens do catálogo nem ao site completo.</p></section>'
    html+=f'<section id="catalogo"><h2>Fotografias de produtos</h2><p>Fonte: <cite>{CATALOGO}</cite>, ficheiro fornecido pela equipa. As fotografias individuais foram extraídas dos objetos de imagem do PDF, compostas sobre fundo branco quando necessário e convertidas para WebP. Não foram ampliadas nem recortadas; a fotografia Stiles foi reduzida para 1200 px no lado maior.</p><p>Autoria individual e licença de reutilização: não identificadas no ficheiro recebido. Não se atribui uma licença Creative Commons a estas fotografias. As marcas e imagens de exemplo presentes nos artigos pertencem à apresentação do catálogo, sem indicar produção da Nobrinde.</p><p>A numeração PDF começa na primeira página do ficheiro. É apresentada também a numeração impressa, que difere ao longo do documento.</p><div class="credit-product-list">'
    for p in PRODUTOS:
        html+=f'<article id="catalogo-{p["id"]}"><h3>{p["nome"]} · {p["ref"]}</h3><p>Fotografia e características: PDF p. {p["pdf"]}; página impressa {p["impressa"]}.</p><a href="assets/produtos/{p["ficheiro"]}">Ver a fotografia extraída</a></article>'
    html+='</div></section><section id="tampografia-provisoria"><h2>Imagens provisórias de tampografia</h2><p>Ficheiros fornecidos pela equipa: autoria, fonte original e licença não identificadas. <strong>Origem e autorização de publicação por confirmar.</strong> Não são atribuídos à Nobrinde. Apresentação sem ampliação, recorte ou outras alterações.</p><ul><li>processo-tampografia-6-passos.jpg — esquema usado em «Como funciona».</li><li>tampoes-silicone-tampografia.jpg — fotografia usada em «Componentes».</li><li>maquina-tampografia-exemplos.jpg — montagem ilustrativa de terceiros usada em «Equipamentos».</li><li>processo-tampografia-5-passos.jpg — guardado na pasta; não mostrado no artigo.</li></ul><p>Estes ficheiros não herdam a licença da fotografia de tampografia creditada acima. As marcas visíveis não comprovam autoria nem autorização de reutilização.</p><div>'
    html+='</div></section><section id="serigrafia-provisoria"><h2>Imagens provisórias de serigrafia</h2><p>Origem e autorização de publicação por confirmar. Estas imagens não representam equipamentos da Nobrinde nem herdam a licença da fotografia principal.</p><ul><li>maquina-carrossel-serigrafia-verde.jpg — exemplo ilustrativo na secção Equipamento, sem ampliação ou recorte.</li><li>maquina-carrossel-serigrafia-azul.jpg — reservada para a página de máquinas.</li><li>funcionamento-tela-serigrafia.jpg — não publicada; substituída por um esquema legível em português.</li><li>etapas-serigrafia-referencia.jpg — referência interna, não publicada.</li></ul></section>'
    html+='<section id="uv-provisoria"><h2>Imagens provisórias de impressão UV</h2><p>Origem e autorização de publicação por confirmar. Não representam instalações ou equipamentos da Nobrinde. A licença da fotografia principal não se estende a estes ficheiros.</p><ul><li>impressao-uv-em-curso.jpg — junto dos passos.</li><li>impressora-uv-mesa.jpg — equipamento ilustrativo.</li><li>impressao-uv-painel-colorido.jpg — exemplo de impressão plana.</li><li>impressora-uv-grande-formato.jpg — reservada para a página de máquinas; representa outra escala de trabalho e não é exibida no guia da técnica.</li></ul><p>As três imagens apresentadas conservam as proporções e não são ampliadas.</p></section>'
    html+='<section id="sublimacao-fornecidas"><h2>Imagens fornecidas para Sublimação</h2><p>Quatro imagens fornecidas pelo utilizador, que autorizou expressamente a sua utilização neste projeto em 28 de setembro de 2026. A autoria e a fonte original não estão documentadas; não se atribui uma licença aberta nem se infere a origem a partir dos nomes dos ficheiros. Não representam instalações ou capacidades da Nobrinde.</p><ul><li>Imagem ChatGPT 28_09_2026, 16_21_36.jpg — composição de equipamento e consumíveis.</li><li>Imagem ChatGPT 28_09_2026, 16_21_32.jpg — prensa e acessórios.</li><li>Imagem ChatGPT 28_09_2026, 16_21_23.jpg — prensa plana e exemplos de peças; a montagem não demonstra compatibilidade com sublimação.</li><li>Imagem ChatGPT 28_09_2026, 16_21_39.jpg — impressão têxtil de tecnologia não identificada.</li></ul><p>Originais conservados em assets/tecnicas/Sublimacao/, sem edição, conversão ou recorte. Apresentados com as proporções originais, até 474 píxeis de largura. A autorização do utilizador fica registada; a documentação da origem e de eventuais direitos de terceiros continua pendente.</p></section>'
    html+='<section id="bordado-fornecidas"><h2>Imagens fornecidas para Bordado</h2><p>Utilização neste projeto expressamente autorizada pelo utilizador em 29 de setembro de 2026. Ficheiros fornecidos em assets/tecnicas/Bordado/. A autoria e a fonte original não estão documentadas; não se atribui uma licença aberta nem se apresentam estas imagens como produção da Nobrinde.</p><ul><li>unnamed.jpg — máquina com bastidor.</li><li>unnamed-2.jpg — duas configurações de equipamento.</li><li>unnamed-3.jpg — motivos florais com textura de fios; o método de criação e execução não está confirmado.</li></ul><p>Originais conservados sem edição, conversão ou recorte, apresentados nas proporções originais e sem ampliação. A autorização do utilizador fica registada; a identificação da autoria e da origem continua pendente. A licença da fotografia Wikimedia Commons não se estende a estes ficheiros.</p></section>'
    html+='<section id="transfers-fornecidas"><h2>Imagens fornecidas para Transfers</h2><p>Utilização neste projeto expressamente autorizada pelo utilizador em 30 de setembro de 2026. Originais em assets/tecnicas/Transfers/, conservados sem edição, conversão ou recorte. A autoria e a fonte original continuam por documentar; não se atribui uma licença aberta. Não representam equipamentos ou produção da Nobrinde.</p><ul><li>Transfer Serigrafico/unnamed.jpg — tela com tinta amarela.</li><li>Transfer Serigrafico/unnamed (20).jpg — prensa e acessórios.</li><li>Transfer Digital/unnamed (23).jpg — impressora com material em rolo.</li><li>DTF/unnamed (27).jpg — montagem de equipamento e consumíveis.</li><li>DTF/unnamed (28).jpg — montagem de equipamentos e t-shirts.</li></ul><p>As fotografias ilustram elementos visíveis e não comprovam compatibilidade ou parâmetros de aplicação. Apresentadas nas proporções originais, até 474 píxeis de largura.</p></section>'
    html+='<section id="troquelagem-fornecidas"><h2>Imagens fornecidas para Troquelagem</h2><p>Ficheiros locais indicados pelo utilizador para este projeto em 7 de outubro de 2026, em assets/tecnicas/Troquelagem/. Autoria, fonte original e licença de terceiros por documentar; não se presume uma licença aberta. Não representam instalações, equipamentos ou produção da Nobrinde.</p><ul><li>unnamed (32).jpg — equipamento manual de bancada e recortes decorativos, 474 × 474 píxeis.</li><li>unnamed (33).jpg — esquema de ferramenta e folha sobre uma placa, 474 × 206 píxeis.</li></ul><p>Originais conservados sem edição, conversão ou recorte, apresentados na proporção natural e sem ampliação. As imagens ilustram elementos visíveis; não são fontes técnicas nem comprovam materiais aceites ou capacidades de produção.</p></section>'
    html+='<section id="crachas-fornecida"><h2>Imagem fornecida para Crachás tipo pin/botão</h2><p>Ficheiro local indicado pelo utilizador para este projeto em 7 de outubro de 2026: assets/tecnicas/Crachas/pack-inicial-chapas-evolution-principal_1.jpg, 360 × 360 píxeis. Mostra uma prensa com alavanca, matrizes e componentes. Não representa equipamentos ou produção da Nobrinde e não comprova produção automática.</p><p>Original conservado sem edição, recorte ou ampliação, com proporção natural. Autoria, fonte original e licença de terceiros por documentar; não se presume uma licença aberta. A utilização local foi solicitada pelo utilizador.</p></section>'
    html+='<section id="montagem-fornecidas"><h2>Imagens de Costura, Argolagem e Encadernação</h2><p>Imagens locais cuja utilização neste projeto foi solicitada pelo utilizador em 7 de outubro de 2026. Pasta original: assets/tecnicas/Costura_Argolagem_Encardenacao/. Autoria, fonte original e licença de terceiros por documentar; não se presume uma licença aberta. Não representam instalações, equipamentos ou produção da Nobrinde.</p><ul><li>Costura_Industrial/unnamed (37).jpg — pormenor de costura à máquina, 474 × 266 píxeis.</li><li>Argolagem/unnamed (41).jpg — equipamento, espirais contínuas e alicate, 474 × 487 píxeis; composição dos consumíveis não confirmada pela imagem.</li><li>Encardenacao/unnamed (45).jpg — trabalho manual com linha na lombada de cadernos de papel, 474 × 474 píxeis.</li></ul><p>Originais preservados sem edição ou recorte, apresentados com proporções naturais e sem ampliação. As fontes técnicas não comprovam a origem nem a licença destas fotografias.</p></section>'
    html+='<section id="materiais-pele-fornecida"><h2>Fotografia do cartão Pele e imitação de pele</h2><p>Fotografia local fornecida e indicada pelo utilizador em 12 de outubro de 2026: assets/materiais/Pele/z_0_nb224514_TARJETERO-PIEL.jpg, 500 × 500 píxeis. Mostra uma carteira castanha com superfície texturada e pespontos; a composição do material não é confirmada pela fotografia. Original preservado sem edição, conversão ou recorte, apresentado na proporção natural.</p><p>Autoria, fonte original e licença de terceiros por documentar; não se presume uma licença aberta. A utilização local neste cartão foi solicitada pelo utilizador.</p></section>'
    html+='<section id="materiais-papel-vidro-fornecidas"><h2>Fotografias dos cartões Papel e cartão e Vidro e cerâmica</h2><p>Fotografias locais fornecidas e indicadas pelo utilizador em 12 de outubro de 2026.</p><ul><li>assets/materiais/Papel_Cartao/z_0_nb222831_PASTA-HABORG.jpg — pasta castanha aberta com abas interiores, 700 × 700 píxeis.</li><li>assets/materiais/Vidro/z_0_nb224623_TROFEU-BOLA-MUNDO-GRANDE.jpg — troféu transparente em forma de globo com mapa e base facetada, 500 × 500 píxeis.</li></ul><p>Originais preservados sem edição, conversão ou recorte, apresentados na proporção natural. As fotografias não confirmam a composição dos objetos. Autoria, fonte original e licença de terceiros por documentar; não se presume uma licença aberta. A utilização local nestes cartões foi solicitada pelo utilizador.</p></section>'
    return html+'<section id="esquemas-industria"><h2>Esquemas da indústria</h2><p>Cronologia e esquemas originais desta biblioteca, construídos em HTML e CSS. São representações simplificadas, sem fotografias de instalações. As cinco fotografias das técnicas são também utilizadas nos guias de máquinas, com os mesmos autores, licenças e alterações indicados acima.</p></section>'
